                    for (cidx, clineno, var) in captures:
                        if cidx < idx:
                            after = "\n".join(lines[idx+1:])
                            if re.search(r'\b' + re.escape(var) + r'\b', after):
                                chains.append({
                                    "path": path, "caller": fname, "caller_start": s+1,
                                    "capture_line": clineno, "var": var,
